mapper.select:
WITH selected_lots AS (
), spaces AS ( SELECT COUNT(*) AS total_spaces, COUNT(*) FILTER (WHERE s.status = 'FREE') AS free_spaces, COUNT(*) FILTER (WHERE s.status = 'OCCUPIED') AS occupied_spaces, COUNT(*) FILTER (WHERE s.status = 'DISABLED') AS disabled_spaces FROM parking_space s JOIN parking_area a ON a.id = s.area_id JOIN selected_lots l ON l.id = a.parking_lot_id ), entries AS ( SELECT COUNT(*) AS entry_count FROM parking_record r JOIN selected_lots l ON l.id = r.parking_lot_id WHERE r.entry_time >= #{fromTime} AND r.entry_time < #{toTime} ), exits AS ( SELECT COUNT(*) AS exit_count FROM parking_record r JOIN selected_lots l ON l.id = r.parking_lot_id WHERE r.exit_time >= #{fromTime} AND r.exit_time < #{toTime} ), revenue AS ( SELECT COALESCE(SUM(p.amount_paid), 0.00) AS total_revenue
) SELECT s.total_spaces, s.free_spaces, s.occupied_spaces, s.disabled_spaces, i.entry_count, x.exit_count, p.total_revenue FROM spaces s CROSS JOIN entries i CROSS JOIN exits x CROSS JOIN revenue p WHERE EXISTS (SELECT 1 FROM selected_lots)

WITH selected_lots AS (
), totals AS ( SELECT COUNT(*) AS payment_count, COALESCE(SUM(p.amount_paid), 0.00) AS total_revenue
) SELECT payment_count, total_revenue FROM totals WHERE EXISTS (SELECT 1 FROM selected_lots)
